from ute_btssm.templatesession import new_session
from ute_btssm.exception import BTSSMExecutionError
from .base_trs_cli import BaseTRSCLIInterface
from collections import OrderedDict


class PasswordConfiguratorInterface(BaseTRSCLIInterface):

    CONFIGURE_PW_OPERATION = 'configurepassword'

    def configure_password(self, new_pw, timeout='5min', **kwargs):
        """Configure BTSSM password through the TRS commandline tools.

        Password should fulfill the following requirements:
        Min. 8 and max. 128 characters.
        At least two numbers, both upper and lower case characters, no two same characters consecutively.
        At least one non-alphanumeric character.
        The password should not be the same as the user name.

        :param string  new_pw: New BTSSM credentials

        :return: The UNIX status return message after executing the configure password java command.
        :rtype: string

        :raises: BTSSMExecutionError: Raised when an UNIX error message is returned after
                 executing the added java command as well as other internal system errors.
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        timeout = self._convert_to_secs(timeout)
        params = OrderedDict([('pwnew', new_pw), ('ne', ne), ('pw', pw)])
        with new_session.NewSession(alias, config, timeout=timeout) as session:
            configure_password_command = session.cmd_builder.trs_tool.build(params=params)
            session.executor.run_via_shell(cmd=configure_password_command,
                                           op=PasswordConfiguratorInterface.CONFIGURE_PW_OPERATION)
            status_message = session.executor.run_via_shell(cmd=BaseTRSCLIInterface.READ_LOG_FILE_CMD,
                                                            op=PasswordConfiguratorInterface.CONFIGURE_PW_OPERATION)
            self._check_for_errors(status_message)
            return status_message
